/**
 * Figures for the oracles, teachers and distillation primer
 * (web/content/learn/techniques/oracle-distillation.mdx).
 *
 * The toy is the maze with a map. The one Drop7 position is read from
 * web/content/learn/oracle-scenario.json, generated by
 * web/scripts/generate-oracle-scenario.ts with the TypeScript engine in latent
 * mode from the figure seed domain; it is a playground position, never
 * gameplay evidence, and no research number appears here. Server components:
 * SVG with CSS keyframes in ./oracle-distillation.css on elements marked
 * data-anim. Every figure is complete at its first frame and rests on a
 * designed frame under prefers-reduced-motion.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ReactNode } from "react";
import { CellGlyph } from "@/components/discs";
import "./oracle-distillation.css";

const MONO = "var(--font-mono)";
const SANS = "var(--font-sans)";
const INK = "var(--color-ink)";
const INK1 = "var(--color-ink-1)";
const INK2 = "var(--color-ink-2)";
const INK3 = "var(--color-ink-3)";
const RULE = "var(--color-rule-strong)";
const SURFACE = "var(--color-surface)";
const RAISED = "var(--color-raised)";
const ACCENT = "var(--color-accent)";
const ORACLE = "var(--color-reads-oracle)";
const PUBLIC = "var(--color-reads-public)";
const BLOCKED = "var(--color-series-7)";

function Fig({ viewBox, label, caption, children }: { viewBox: string; label: string; caption: string; children: ReactNode }) {
  return (
    <figure className="fig primer-oracle">
      <div className="fig-frame">
        <svg viewBox={viewBox} role="img" aria-label={label}>
          {children}
        </svg>
      </div>
      <figcaption>{caption}</figcaption>
    </figure>
  );
}

interface OracleScenario {
  seed: string;
  board: string;
  oracle: string;
  covered: number[];
}

function loadOracleScenario(): OracleScenario | null {
  const path = join(process.cwd(), "content", "learn", "oracle-scenario.json");
  if (!existsSync(path)) return null;
  return JSON.parse(readFileSync(path, "utf8")) as OracleScenario;
}

/** A 7 by 7 board from the engine's row-major cell string. */
function Board7({ cells, x, y, s }: { cells: string; x: number; y: number; s: number }) {
  const glyphs: ReactNode[] = [];
  for (let i = 0; i < 49; i += 1) {
    const row = Math.floor(i / 7);
    const col = i % 7;
    glyphs.push(<CellGlyph key={i} cell={Number(cells[i])} x={x + col * s} y={y + row * s} s={s} />);
  }
  return <g>{glyphs}</g>;
}

/* =========================================================================
 * 1. The boundary: the same position seen twice, and what may cross.
 * ========================================================================= */

export function OracleBoundary() {
  const data = loadOracleScenario();
  if (!data) {
    return (
      <figure className="fig primer-oracle">
        <div className="fig-frame">
          <p style={{ color: INK3, fontSize: 13, margin: "1rem" }}>
            The boundary position is not available in this checkout. Run <code>npm run figures:oracle</code> inside <code>web/</code> to
            regenerate <code>content/learn/oracle-scenario.json</code>.
          </p>
        </div>
      </figure>
    );
  }
  const s = 20;
  const leftX = 30;
  const rightX = 390;
  const boardY = 62;
  const lineX = 280;
  // Three hidden values from the answer key, taken from the first covered row.
  const hiddenRow = Math.floor(data.covered[0] / 7);
  const samples = data.covered.filter((i) => Math.floor(i / 7) === hiddenRow).slice(0, 3);
  return (
    <Fig
      viewBox="0 0 560 276"
      label="The same board twice: on the left with every hidden number visible, on the right with gray covers; a vertical line between them that a single column label crosses and the numbers do not"
      caption={`One position from a playground game (seed ${data.seed}), shown as the teacher sees it on the left, with every hidden number filled in, and as the student sees it on the right, with ${data.covered.length} covered discs. The teacher's chosen column is the only thing allowed across the line; the hidden values stop at it.`}
    >
      <text x={lineX} y={22} textAnchor="middle" fontFamily={MONO} fontSize={10.5} fill={INK2}>
        the information boundary
      </text>
      <line x1={lineX} y1={32} x2={lineX} y2={256} stroke={INK2} strokeWidth={2} />

      <text x={leftX + 70} y={46} textAnchor="middle" fontFamily={MONO} fontSize={10.5} fill={ORACLE}>
        the teacher sees
      </text>
      <Board7 cells={data.oracle} x={leftX} y={boardY} s={s} />
      <text x={leftX + 70} y={boardY + 7 * s + 18} textAnchor="middle" fontFamily={SANS} fontSize={10.5} fill={INK3}>
        every hidden number, and the discs to come
      </text>

      <text x={rightX + 70} y={46} textAnchor="middle" fontFamily={MONO} fontSize={10.5} fill={PUBLIC}>
        the student sees
      </text>
      <Board7 cells={data.board} x={rightX} y={boardY} s={s} />
      <text x={rightX + 70} y={boardY + 7 * s + 18} textAnchor="middle" fontFamily={SANS} fontSize={10.5} fill={INK3}>
        {`${data.covered.length} covered discs, values unknown`}
      </text>

      {/* Hidden values pressing against the line and stopping there. */}
      <g transform="translate(256 84)">
        <g data-anim="number" opacity={0.3}>
          {samples.map((index, k) => (
            <CellGlyph key={index} cell={Number(data.oracle[index])} x={0} y={k * 24} s={18} />
          ))}
        </g>
      </g>
      {samples.map((index, k) => (
        <path key={index} d={`M${lineX - 3} ${90 + k * 24}l6 6M${lineX + 3} ${90 + k * 24}l-6 6`} stroke={BLOCKED} strokeWidth={1.6} />
      ))}
      <text x={lineX - 8} y={170} textAnchor="end" fontFamily={MONO} fontSize={9.5} fill={INK3}>
        hidden values stop here
      </text>

      {/* The label that crosses. */}
      <g transform="translate(296 200)">
        <g data-anim="pill">
          <rect width={78} height={22} rx={11} fill={SURFACE} stroke={ACCENT} strokeWidth={1.4} />
          <text x={39} y={15} textAnchor="middle" fontFamily={MONO} fontSize={10} fill={ACCENT}>
            one column
          </text>
        </g>
      </g>
      <text x={lineX + 8} y={240} fontFamily={MONO} fontSize={9.5} fill={INK3}>
        the label crosses
      </text>
    </Fig>
  );
}

/* =========================================================================
 * 2. Two junctions that look the same from inside the corridor.
 * ========================================================================= */

function Junction({ cx, turn }: { cx: number; turn: "left" | "right" }) {
  const floorY = 100;
  const floorH = 40;
  const stemW = 40;
  const wall = RULE;
  return (
    <g>
      {/* corridor floor */}
      <rect x={cx - 92} y={floorY} width={184} height={floorH} fill={SURFACE} />
      <rect x={cx - stemW / 2} y={floorY + floorH} width={stemW} height={62} fill={SURFACE} />
      {/* walls */}
      <path
        d={`M${cx - 92} ${floorY}H${cx + 92}M${cx - 92} ${floorY + floorH}H${cx - stemW / 2}V${floorY + floorH + 62}M${cx + 92} ${floorY + floorH}H${cx + stemW / 2}V${floorY + floorH + 62}`}
        stroke={wall}
        strokeWidth={5}
        fill="none"
      />
      {/* the ends fade into what the student cannot see */}
      <rect x={cx - 92} y={floorY - 3} width={26} height={floorH + 6} fill={RAISED} opacity={0.85} />
      <rect x={cx + 66} y={floorY - 3} width={26} height={floorH + 6} fill={RAISED} opacity={0.85} />
      <text x={cx - 79} y={floorY + 25} textAnchor="middle" fontFamily={MONO} fontSize={12} fill={INK3}>
        ?
      </text>
      <text x={cx + 79} y={floorY + 25} textAnchor="middle" fontFamily={MONO} fontSize={12} fill={INK3}>
        ?
      </text>
      {/* the student */}
      <circle cx={cx} cy={floorY + floorH + 44} r={7} fill={PUBLIC} />
      <path d={`M${cx} ${floorY + floorH + 34}v-22`} stroke={PUBLIC} strokeWidth={1.4} strokeDasharray="2 3" />
      {/* the map inset */}
      <g transform={`translate(${cx + 24} 12)`}>
        <rect width={104} height={70} rx={6} fill={RAISED} stroke={ORACLE} strokeWidth={1.2} />
        <text x={52} y={13} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={ORACLE}>
          the map
        </text>
        <path d="M14 44H90M52 44V62" stroke={INK3} strokeWidth={4} fill="none" strokeLinecap="round" />
        {turn === "left" ? (
          <>
            <path d="M52 62V44H14V26" stroke={ORACLE} strokeWidth={2.4} fill="none" strokeLinecap="round" />
            <path d="M90 44V30" stroke={INK3} strokeWidth={4} strokeLinecap="round" />
            <path d="M84 30h12" stroke={INK3} strokeWidth={4} strokeLinecap="round" />
            <text x={14} y={22} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={ORACLE}>
              exit
            </text>
          </>
        ) : (
          <>
            <path d="M52 62V44H90V26" stroke={ORACLE} strokeWidth={2.4} fill="none" strokeLinecap="round" />
            <path d="M14 44V30" stroke={INK3} strokeWidth={4} strokeLinecap="round" />
            <path d="M8 30h12" stroke={INK3} strokeWidth={4} strokeLinecap="round" />
            <text x={90} y={22} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={ORACLE}>
              exit
            </text>
          </>
        )}
      </g>
      <text x={cx} y={228} textAnchor="middle" fontFamily={SANS} fontSize={10.5} fill={INK2}>
        {`what the student sees is identical · the map says turn ${turn}`}
      </text>
    </g>
  );
}

export function OracleTwoJunctions() {
  return (
    <Fig
      viewBox="0 0 560 240"
      label="Two T-junctions drawn identically from the student's side, each with a map inset showing a different correct turn"
      caption="Two junctions in two mazes. From inside the corridor the student sees the same thing at both, and the map says turn left at one and turn right at the other. A student trained to copy the map's turns has to answer both from the same view, so it is wrong at one of them however it is trained."
    >
      <Junction cx={140} turn="left" />
      <Junction cx={420} turn="right" />
    </Fig>
  );
}

/* =========================================================================
 * 3. The DAgger loop: the teacher relabels wherever the student ends up.
 * ========================================================================= */

function Box({ x, y, w, h, stroke, title, sub }: { x: number; y: number; w: number; h: number; stroke: string; title: string; sub?: string }) {
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx={8} fill={RAISED} stroke={stroke} strokeWidth={1.4} />
      <text x={x + w / 2} y={y + (sub ? 21 : 30)} textAnchor="middle" fontFamily={SANS} fontSize={12} fontWeight={600} fill={INK}>
        {title}
      </text>
      {sub && (
        <text x={x + w / 2} y={y + 38} textAnchor="middle" fontFamily={MONO} fontSize={9.5} fill={INK2}>
          {sub}
        </text>
      )}
    </g>
  );
}

function Arrow({ d }: { d: string }) {
  return <path d={d} stroke={INK2} strokeWidth={1.6} fill="none" markerEnd="url(#primer-oracle-arrow)" />;
}

export function OracleDaggerLoop() {
  return (
    <Fig
      viewBox="0 0 560 250"
      label="Four boxes: the teacher plays once, feeding labels; labels train a student that plays; the teacher relabels the positions the student reached; those labels join the pool; a dot travels the loop"
      caption="The teacher plays once and its logged choices become the first labels. From then on the loop runs on the right: the student is trained and plays on its own, the teacher is asked what it would have done at every position the student reached, and those answers join the labels. The travelling dot follows the loop. Boxes on the teacher's side of the boundary are outlined in the oracle colour."
    >
      <defs>
        <marker id="primer-oracle-arrow" viewBox="0 0 10 10" refX={9} refY={5} markerWidth={7} markerHeight={7} orient="auto-start-reverse">
          <path d="M0 0L10 5L0 10z" fill={INK2} />
        </marker>
      </defs>
      <Box x={10} y={28} w={132} h={50} stroke={ORACLE} title="teacher plays" sub="once, with everything visible" />
      <Box x={206} y={28} w={150} h={50} stroke={INK3} title="labels" sub="public view, teacher's move" />
      <Box x={356} y={152} w={188} h={50} stroke={PUBLIC} title="student plays" sub="trained on the labels, blind" />
      <Box x={20} y={152} w={200} h={50} stroke={ORACLE} title="teacher relabels" sub="the positions the student reached" />

      <Arrow d="M142 53H203" />
      <Arrow d="M332 78L418 150" />
      <Arrow d="M356 177H223" />
      <Arrow d="M160 152L238 80" />

      <text x={172} y={44} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={INK3}>
        first labels
      </text>
      <text x={400} y={108} fontFamily={MONO} fontSize={9} fill={INK3}>
        train, then walk
      </text>
      <text x={290} y={192} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={INK3}>
        where did it end up?
      </text>
      <text x={150} y={118} textAnchor="end" fontFamily={MONO} fontSize={9} fill={INK3}>
        more labels
      </text>

      <g transform="translate(281 53)">
        <g data-anim="dot">
          <circle r={6} fill={ACCENT} />
        </g>
      </g>

      <text x={280} y={236} textAnchor="middle" fontFamily={SANS} fontSize={10.5} fill={INK1}>
        every lap adds labels at the student&apos;s own positions; the labels are still the teacher&apos;s reasons
      </text>
    </Fig>
  );
}
